from itertools import permutations

def is_latin_square(x):
    n = 6
    for i in range(n):
        if sorted(x[i*n:(i+1)*n]) != list(range(n)):
            return False
    for j in range(n):
        column = [x[i*n+j] for i in range(n)]
        if sorted(column) != list(range(n)):
            return False
    return True


def is_idempotent(x):
    n = 6
    for i in range(n):
        if x[i*n+i] != i:
            return False
    return True


def is_qg3(x):
    n = 6
    for i in range(n):
        for j in range(n):
            if x[x[i*n+j]*n+x[j*n+i]] != i:
                return False
    return True


def find_quasigroup):
    n = 6
    for p in permutations(range(n)):
        for q in permutations(range(n)):
            for r in permutations(range(n)):
                for s in permutations(range(n)):
                    for t in permutations(range(n)):
                        for u in permutations(range(n)):
                            x = list(p) + list(q) + list(r) + list(s) + list(t) + list(u)
                            if is_latin_square(x) and is_idempotent(x) and is_qg3(x):
                                return x
    return "UNSATISFIABLE"

print(find_quasigroup())

