from itertools import combinations

def find_coloring():
    # Generate all edges in lexicographic order
    edges = list(combinations(range(20), 2))

    # Initialize the coloring with all edges as red (0)
    coloring = [0] * len(edges)

    # Function to check if a clique is monochromatic
    def is_monochromatic(clique, color):
        for i in range(len(clique)):
            for j in range(i+1, len(clique)):
                edge = (clique[i], clique[j])
                edge_index = edges.index(edge)
                if coloring[edge_index] != color:
                    return False
        return True

    # Try to find a valid coloring
    for i in range(len(edges)):
        # Check if making this edge blue would create a monochromatic blue clique of size 4
        if is_monochromatic([edges[i][0], edges[i][1], edges[(i+1)%len(edges)][0], edges[(i+2)%len(edges)][0]], 1):
            continue

        # Check if making this edge red would create a monochromatic red clique of size 5
        if is_monochromatic([edges[i][0], edges[i][1], edges[(i+1)%len(edges)][0], edges[(i+2)%len(edges)][0], edges[(i+3)%len(edges)][0]], 0):
            coloring[i] = 1
        else:
            coloring[i] = 0

    return coloring

